sections.usage:
```
Act as an AutoGroq AI agent team lead. Create a dynamic team of specialized AI agents to [TASK: e.g., 'analyze TOMI app user engagement metrics and propose monetization strategies']. The team should include: 1) Data Analyst Agent, 2) Monetization Strategist Agent, 3) Community Growth Agent, 4) Competitive Research Agent, and 5) Output Formatter Agent. Use [TOMI_APP_DATA] and [MARKET_TRENDS] as inputs where applicable. Deliver a structured report with actionable recommendations.
```
Copy

```
{
  "project_title": "TOMI App Monetization Strategy Analysis",
  "executive_summary": "Analysis of TOMI app's user engagement and monetization potential reveals three high-impact opportunities: 1) Premium subscription tiers for power users averaging 15+ daily interactions, 2) Creator monetization program with 20% revenue share for top 5% of content producers, and 3) Strategic partnerships with crypto gaming platforms to drive user acquisition. Current user retention stands at 42% month-over-month with $2.8M in annual transaction volume.",
  "team_breakdown": {
    "data_analyst_agent": {
      "findings": {
        "daily_active_users": 125000,
        "avg_session_duration": 8.3 minutes,
        "top_user_countries": ["USA", "India", "Nigeria"],
        "premium_conversion_rate": 3.2%,
        "revenue_per_user": $22.40 annually
      }
    },
    "monetization_strategist_agent": {
      "recommendations": [
        {
          "strategy": "Tiered Subscription Model",
          "details": "Basic ($4.99/mo), Pro ($14.99/mo with 0% transaction fees), Elite ($29.99/mo with premium support and early access to features",
          "projected_revenue": "$1.8M annually from 15% of user base",
          "implementation_timeline": "3 months"
        },
        {
          "strategy": "Creator Revenue Share Program",
          "details": "5-20% revenue share based on engagement metrics, with minimum $100 payout threshold",
          "projected_revenue": "$850K annually from 2000 active creators",
          "implementation_timeline": "6 weeks"
        }
      ]
    },
    "community_growth_agent": {
      "strategies": [
        "Launch referral program offering $5 crypto credit for every 3 successful referrals",
        "Create weekly 'Creator Spotlight' in-app feature to boost engagement",
        "Partner with 5 crypto influencers for cross-promotion campaigns"
      ],
      "projected_impact": "25% increase in monthly active users within 6 months"
    },
    "competitive_research_agent": {
      "key_findings": {
        "Telegram Stars": "$100M+ annual revenue with 50M+ users",
        "Discord Server Subscriptions": "$50M+ annual revenue with 15% conversion rate",
        "Signal Premium": "Limited monetization success due to privacy focus"
      },
      "differentiation_opportunities": [
        "Seamless crypto integration vs. fiat-only competitors",
        "Built-in wallet with staking features",
        "Community governance features"
      ]
    }
  },
  "implementation_plan": {
    "phase_1": {
      "duration": "4 weeks",
      "actions": [
        "Deploy premium subscription tiers",
        "Launch creator revenue share program",
        "Integrate referral program"
      ]
    },
    "phase_2": {
      "duration": "8 weeks",
      "actions": [
        "Implement community growth initiatives",
        "Establish crypto gaming partnerships",
        "Expand to 3 new markets (Brazil, Vietnam, Philippines)"
      ]
    }
  },
  "risk_assessment": {
    "high_risk": [
      "Regulatory uncertainty around crypto payments in target markets",
      "Potential user backlash against monetization changes"
    ],
    "mitigation_strategies": [
      "Consult legal experts in target jurisdictions",
      "Gradual rollout with extensive A/B testing",
      "Transparent communication about revenue use for platform improvements"
    ]
  }
}
```

